-- Optional starter data. Safe to run once after migrate; uses ON CONFLICT DO NOTHING
-- so re-running it never duplicates rows.

INSERT INTO jobs (id, title, type, shift, salary_range, summary, requirements, is_open) VALUES
  ('sales-associate', 'พนักงานขายหน้าร้าน', 'เต็มเวลา / พาร์ทไทม์', 'หมุนเวียนตามกะ', '12,000 บาทขึ้นไป (ตามประสบการณ์)', 'ต้อนรับลูกค้า แนะนำสินค้า จัดเรียงสินค้าและดูแลความเรียบร้อยหน้าร้าน', 'วุฒิ ม.3 ขึ้นไป, อายุ 18 ปีขึ้นไป, บุคลิกดี ยิ้มแย้มแจ่มใส', true),
  ('cashier', 'แคชเชียร์', 'เต็มเวลา / พาร์ทไทม์', 'หมุนเวียนตามกะ', '12,000 - 14,000 บาท', 'รับชำระเงิน ดูแลหน้าเคาน์เตอร์ ตรวจนับเงินประจำวันให้ถูกต้อง', 'ละเอียดรอบคอบ ซื่อสัตย์ มีไหวพริบในการแก้ปัญหาเฉพาะหน้า', true),
  ('stock', 'พนักงานสต๊อก/คลังสินค้า', 'เต็มเวลา', 'กะเช้า / กะบ่าย', '12,500 บาทขึ้นไป', 'รับสินค้าเข้า-ออก ตรวจนับสต๊อก จัดเรียงคลังสินค้าให้เป็นระบบ', 'แข็งแรง ขยัน สามารถยกของและทำงานเป็นทีมได้', true),
  ('asst-manager', 'ผู้ช่วยผู้จัดการสาขา', 'เต็มเวลา', 'ตามตารางสาขา', '16,000 - 20,000 บาท', 'ช่วยบริหารจัดการหน้าร้าน ดูแลทีมงาน ควบคุมยอดขายและสต๊อกสินค้า', 'มีประสบการณ์งานค้าปลีกอย่างน้อย 1 ปี เป็นผู้นำทีมได้', true),
  ('store-manager', 'ผู้จัดการสาขา', 'เต็มเวลา', 'ตามตารางสาขา', '22,000 บาทขึ้นไป + คอมมิชชั่น', 'บริหารสาขาในภาพรวม ดูแลยอดขาย ทีมงาน และมาตรฐานการให้บริการ', 'มีประสบการณ์บริหารร้านค้าปลีกอย่างน้อย 2 ปี', true),
  ('cleaning', 'พนักงานทำความสะอาด', 'พาร์ทไทม์', 'กะเช้า / กะเย็น', '400 - 450 บาท/วัน', 'ดูแลความสะอาดพื้นที่ร้านและบริเวณโดยรอบให้พร้อมบริการลูกค้าเสมอ', 'ขยัน รับผิดชอบ ตรงต่อเวลา', true)
ON CONFLICT (id) DO NOTHING;

INSERT INTO settings (key, value) VALUES
  ('pdpa_policy_text', E'บริษัทฯ จะเก็บรวบรวม ใช้ และเปิดเผยข้อมูลส่วนบุคคลของท่าน (เช่น ชื่อ-นามสกุล เบอร์โทรศัพท์ อีเมล ที่อยู่/พื้นที่ที่สะดวกทำงาน ประวัติการทำงาน รวมถึงเรซูเม่และรูปถ่ายที่แนบมา) เพื่อวัตถุประสงค์ในการพิจารณาคัดเลือกเข้าทำงาน ติดต่อนัดหมายสัมภาษณ์ และดำเนินกระบวนการสรรหาบุคลากรของบริษัทเท่านั้น\n\nข้อมูลของท่านจะถูกเก็บไว้ในระบบของบริษัทและเข้าถึงได้เฉพาะเจ้าหน้าที่ฝ่ายบุคคลที่เกี่ยวข้อง โดยจะไม่ถูกเปิดเผยต่อบุคคลภายนอกโดยไม่ได้รับความยินยอม เว้นแต่กรณีที่กฎหมายกำหนด และจะถูกเก็บไว้ตามระยะเวลาที่จำเป็นต่อกระบวนการสรรหาบุคลากรเท่านั้น\n\nท่านมีสิทธิขอเข้าถึง แก้ไข หรือขอให้ลบข้อมูลส่วนบุคคลของท่านได้ โดยติดต่อทีมงานฝ่ายบุคคลของ CJ Mart'),
  ('pdpa_consent_text', 'ข้าพเจ้าได้อ่านและรับทราบนโยบายความเป็นส่วนตัวข้างต้น และยินยอมให้ CJ Mart เก็บรวบรวม ใช้ และเปิดเผยข้อมูลส่วนบุคคลของข้าพเจ้าเพื่อวัตถุประสงค์ในการสมัครงาน'),
  ('company_overview', E'CJ Mart คือร้านสะดวกซื้อที่เติบโตอย่างต่อเนื่อง มีสาขาให้บริการอยู่ทั่วประเทศ เรามุ่งมั่นสร้างทีมงานที่แข็งแกร่งและเติบโตไปด้วยกัน\n\nไม่ว่าคุณจะเพิ่งเริ่มต้นทำงาน หรือมีประสบการณ์งานค้าปลีกมาแล้ว เรามีตำแหน่งงานหลากหลายรองรับ พร้อมสวัสดิการที่ดีและโอกาสก้าวหน้าในสายอาชีพ'),
  ('social_youtube', ''),
  ('social_tiktok', ''),
  ('social_facebook', ''),
  ('social_instagram', '')
ON CONFLICT (key) DO NOTHING;

